members.head_css:
.faculty-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 16px;
    padding: 10px 26px;
    border-radius: 60px;
    background: var(--color-primary);
    color: #FFFFFF;
    font-weight: 600;
    font-size: 0.95rem;
    font-family: var(--font);
    transition: transform var(--transition), background var(--transition), box-shadow var(--transition);
    text-decoration: none;
}
.faculty-btn:hover {
    background: var(--color-primary-dark);
    transform: scale(1.04);
    box-shadow: 0 6px 20px rgba(232, 93, 4, 0.30);
}
